-- macros/cents_to_euros.sql
{% macro cents_to_euros(col) %} round({{ col }} / 100.0, 2) {% endmacro %}

-- in a model
select order_id, {{ cents_to_euros('amount_cents') }} as amount_eur
from {{ ref('stg_orders') }}

{{ config(
    materialized='incremental',
    incremental_strategy='merge',
    unique_key='offer_id',
    on_schema_change='append_new_columns'
) }}

select offer_id, title, company, status, updated_at
from {{ ref('stg_offers') }}
{% if is_incremental() %}
  -- lookback: re-read 3 days to catch late or updated rows
  where updated_at >= (select {{ dbt.dateadd('day', -3, 'max(updated_at)') }} from {{ this }})
{% endif %}

-- packages.yml (installed with dbt deps):
--   packages:
--     - package: dbt-labs/dbt_utils
--       version: [">=1.1.0", "<2.0.0"]

{% set methods = ['card', 'paypal', 'transfer'] %}

select
    {{ dbt_utils.generate_surrogate_key(['order_id', 'customer_id']) }} as order_key,
    order_id,
    customer_id,
    {% for m in methods %}
    sum(case when payment_method = '{{ m }}' then amount else 0 end) as amount_{{ m }},
    {% endfor %}
    sum(amount) as amount_total
from {{ ref('stg_payments') }}
{% if target.name == 'dev' %}
where created_at >= {{ dbt.dateadd('day', -30, 'current_date') }}
{% endif %}
group by order_id, customer_id

